package com.voicetxt.reader;
import android.app.Instrumentation;import android.os.Bundle;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
public class SentencePlaybackTest extends Instrumentation {
    public void onCreate(Bundle b){super.onCreate(b);start();}
    public void onStart(){Bundle result=new Bundle();OfflineSpeaker offline=new OfflineSpeaker(getTargetContext());SystemSpeaker system=new SystemSpeaker(getTargetContext());try{
        String text="夜幕渐渐低垂，远处的山林传来轻轻的风声，他站在窗边看着缓缓流动的云，想起白天那场没有说完的谈话，又想起临行前朋友认真叮嘱的话语，终于合上手中的书，准备出发。\n她轻声问道：“你准备好了吗？”他点了点头……随后，两个人一起走出了房间。\n";
        ArrayList<String> chunks=new ArrayList<>();StringBuilder rebuilt=new StringBuilder();for(int at=0;at<text.length();){int end=MainActivity.nextSpeechEnd(text,at,text.length());String piece=text.substring(at,end);rebuilt.append(piece);if(!piece.trim().isEmpty())chunks.add(piece);at=end;}if(!rebuilt.toString().equals(text))throw new AssertionError("lost source characters");for(String chunk:chunks)if(chunk.endsWith("准备")||chunk.endsWith("随后"))throw new AssertionError("dangling words after punctuation");result.putInt("chunks",chunks.size());
        CountDownLatch initialized=new CountDownLatch(1);AtomicReference<Throwable> error=new AtomicReference<>();offline.init(e->{error.set(e);initialized.countDown();});if(!initialized.await(45,TimeUnit.SECONDS)||error.get()!=null)throw new AssertionError("offline initialization failed",error.get());CountDownLatch done=new CountDownLatch(1);AtomicInteger cues=new AtomicInteger();offline.speakSequence(chunks,2015,1.8f,new OfflineSpeaker.SequenceListener(){public void buffering(int n){}public void sentence(int index){if(index!=cues.getAndIncrement())error.set(new AssertionError("highlight sequence wrong"));}public void done(){done.countDown();}public void failed(Throwable e){error.set(e);done.countDown();}});if(!done.await(90,TimeUnit.SECONDS)||error.get()!=null)throw new AssertionError("native continuous speech failed",error.get());if(cues.get()!=chunks.size())throw new AssertionError("native dropped chunk");result.putInt("nativeUnderruns",offline.sequenceUnderruns);if(offline.sequenceUnderruns!=0)throw new AssertionError("native playback underrun");
        CountDownLatch ready=new CountDownLatch(1);system.init(()->{if(system.initialized)ready.countDown();});if(!ready.await(30,TimeUnit.SECONDS))throw new AssertionError("system initialization failed");SystemSpeaker.Option choice=system.find(getTargetContext().getSharedPreferences("reading_settings",0).getString("systemVoiceKey",""));if(choice==null)choice=system.offlineVoice("zh","");if(choice==null)throw new AssertionError("no system voice");CountDownLatch spoken=new CountDownLatch(1);AtomicInteger events=new AtomicInteger();system.speak(chunks,choice,1.8f,new SystemSpeaker.Listener(){public void sentence(int i){if(i!=events.getAndIncrement())error.set(new AssertionError("system order wrong"));}public void range(int i,int s,int e){}public void done(){spoken.countDown();}public void failed(){error.set(new AssertionError("system voice failed"));spoken.countDown();}});if(!spoken.await(90,TimeUnit.SECONDS)||error.get()!=null||events.get()!=chunks.size())throw new AssertionError("system continuous speech failed",error.get());result.putString("systemEngine",choice.engineLabel);result.putString("result","PASS: exact text coverage; punctuation-aligned chunks; native male continuous playback with zero underruns; selected system voice completes all chunks in order");offline.close();system.close();finish(-1,result);
    }catch(Throwable e){offline.close();system.close();result.putString("error",android.util.Log.getStackTraceString(e));finish(0,result);}}
}
